		this.scrollFabUpdateScheduled = false;
		this.scrollRAF = 0;
		this.scrollFabRAF = 0;

		// Programmatic page movement must never be interpreted as user intent.
		this.programmaticScrollPending = false;
		this.programmaticScrollTarget = null;

