		this._d('chunk.append', {
			len: s.length,
			nl: Utils.countNewlines(s),
			head: String(s).slice(0, 160),
			tail: String(s).slice(-160),
			hasAngle: /[<>]/.test(String(s)),
			hasFenceToken: /```|~~~/.test(String(s))
		});
