static reEscape(s){return String(s).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');}
static idle(fn,timeout){if('requestIdleCallback'in window)return requestIdleCallback(fn,{timeout:timeout||800});return setTimeout(fn,50);}
